import{c as e,Q as a,j as t,m as i}from"./chunks/framework.DOi4mjdC.js";const d=JSON.parse('{"title":"Ascend C概述","description":"","frontmatter":{},"headers":[{"level":1,"title":"Ascend C概述","slug":"ascend-c概述"},{"level":2,"title":"CANN概述","slug":"cann概述"},{"level":2,"title":"Ascend C简介","slug":"ascend-c简介"},{"level":1,"title":"Ascend C学习路径","slug":"ascend-c学习路径"},{"level":2,"title":"快速入门：快速上手实操，构建全景认知","slug":"快速入门快速上手实操构建全景认知"},{"level":2,"title":"进阶编程：掌握编程模型，实现定制开发","slug":"进阶编程掌握编程模型实现定制开发"},{"level":2,"title":"高级编程：挖掘极限性能，驾驭复杂场景","slug":"高级编程挖掘极限性能驾驭复杂场景"},{"level":2,"title":"技术附录","slug":"技术附录"}],"relativePath":"guide/入门教程/Ascend-C概述与学习路径.md","filePath":"guide/入门教程/Ascend-C概述与学习路径.md"}'),r={name:"guide/入门教程/Ascend-C概述与学习路径.md"};function n(s,l,o,h,c,u){return a(),t("div",null,[...l[0]||(l[0]=[i('<h1 id="ascend-c概述" tabindex="-1">Ascend C概述 <a class="header-anchor" href="#ascend-c概述" aria-label="Permalink to &quot;Ascend C概述&quot;">​</a></h1><h2 id="cann概述" tabindex="-1">CANN概述 <a class="header-anchor" href="#cann概述" aria-label="Permalink to &quot;CANN概述&quot;">​</a></h2><p>AI（Artificial Intelligence，人工智能）芯片是专为加速人工智能计算任务设计的专用处理器，凭借高度并行化的硬件架构，可高效应对深度学习场景中的大规模张量运算。NPU（Neural-Network Processing Unit，神经网络处理器）作为AI芯片的典型代表，其核心优势在于适配神经网络任务的高效执行；昇腾AI处理器作为专用NPU，内部集成大量高性能计算核心，进一步强化了这一硬件优势，为AI任务的高效运行提供坚实支撑。</p><p>在神经网络模型中，算子是构成模型的基础计算单元，封装了针对张量数据的特定数学操作逻辑，如卷积、矩阵乘、激活函数等。神经网络模型的推理与训练过程，本质上是一系列算子按照预设逻辑有序执行、协同完成计算任务的过程。为充分释放昇腾NPU的硬件算力，需构建一套能够高效衔接上层AI框架与底层硬件的软件平台，而CANN（Compute Architecture for Neural Networks）正是华为专为昇腾NPU打造的全栈软件解决方案。</p><p>CANN基于分层架构设计，实现了上层应用与底层硬件的无缝衔接。向上，兼容PyTorch等主流AI框架，确保应用层的兼容性与易用性；向下，深度适配昇腾AI处理器，充分发挥硬件的计算潜能，进而构建起CPU与NPU深度融合的异构计算体系。在该体系中，CANN通过Runtime运行时接口驱动CPU与NPU高效协同调度：CPU完成数据准备、任务拆解与调度后，将算子任务下发至NPU加速执行；计算完成后，结果由CPU回收或根据业务需求进行进一步处理。这一协同机制贯穿算子、模型、应用全层级，有效达成计算性能与运行效率的最优平衡，为昇腾AI处理器算力的充分释放提供核心软件支撑。</p><h2 id="ascend-c简介" tabindex="-1">Ascend C简介 <a class="header-anchor" href="#ascend-c简介" aria-label="Permalink to &quot;Ascend C简介&quot;">​</a></h2><p>大模型时代，算力需求正以前所未有的速度激增。如何开发高性能算子，充分释放硬件每一分潜能，已成为决定AI应用落地的关键。为帮助开发者高效构建可直接运行于NPU的高性能算子，Ascend C应运而生。Ascend C是CANN生态下，面向昇腾AI处理器推出的专用算子开发语言，原生兼容C与C++标准规范。此外，Ascend C秉持<strong>开放芯片完备编程能力，支撑极致性能</strong>的设计理念，构建多层级API体系，满足多场景算子开发诉求，让您能够根据项目需求、团队技能和性能目标，在开发效率与运行性能之间灵活权衡，实现最优平衡。</p><p>为满足不同场景的诉求，Ascend C构建了从单指令抽象、单核公共算法到多核算子的多层级API体系，其总体逻辑架构如下：</p><p>&lt;img src=&quot;../../figures/architecture.png&quot; alt=&quot;架构图&quot; width=&quot;850px&quot; height=&quot;580px&quot;&gt;</p><ul><li><strong>语言扩展层C API</strong>：纯C接口，提供数组内存分配、基于指针的计算接口，延续业界熟悉的C编程体验，并完整开放芯片能力。Ascend 950PR/Ascend 950DT新增SIMT、SIMD/SIMT混合编程能力。</li><li><strong>基础API</strong>：以单指令为抽象的C++类库，一般基于Tensor编程，并逐步通过Layout完善Tensor编程体验。</li><li><strong>高阶API</strong>：对单核常见算法进行抽象与封装，提供开箱即用的公共算法实现。</li><li><strong>算子模板库</strong>：基于模板提供算子的完整实现参考，降低Tiling开发复杂度，支持用户自定义扩展。</li><li><strong>Python前端PyAsc</strong>：基于Python原生接口（参见 <a href="https://gitcode.com/cann/pyasc" target="_blank" rel="noreferrer">PyAsc</a>），提供芯片底层完备编程能力，并将逐步引入Layout化Tensor编程、SIMT编程等，实现用Python开发高性能算子。</li></ul><blockquote><p>💡 如何选择多级API，可参考 <a href="./../../asc_how_to_choose_api.html">Ascend C多级API选择指南</a>。</p></blockquote><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>Ascend C支持在如下AI处理器型号上使用：</p><ul><li>Atlas 350 加速卡</li><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li><li>Atlas 200I/500 A2 推理产品</li><li>Atlas 推理系列产品</li><li>Atlas 训练系列产品</li></ul></div><hr><h1 id="ascend-c学习路径" tabindex="-1">Ascend C学习路径 <a class="header-anchor" href="#ascend-c学习路径" aria-label="Permalink to &quot;Ascend C学习路径&quot;">​</a></h1><h2 id="快速入门-快速上手实操-构建全景认知" tabindex="-1">快速入门：快速上手实操，构建全景认知 <a class="header-anchor" href="#快速入门-快速上手实操-构建全景认知" aria-label="Permalink to &quot;快速入门：快速上手实操，构建全景认知&quot;">​</a></h2><p>初级阶段的目标是让您在最短时间内跑通第一个算子，理解Ascend C的基本工作方式。</p><p>学习路线建议如下：</p><ul><li><strong>环境搭建</strong>：从 <a href="./环境准备.html">CANN环境安装</a> 开始，准备好开发与运行环境。</li><li><strong>编程模型概览</strong>：阅读 <a href="./快速入门/异构系统与编程模型.html">异构系统与SIMD/SIMT编程模型介绍</a>，建立对昇腾AI处理器异构计算以及SIMD、SIMT两种执行模型的整体认识。</li><li><strong>动手实践</strong>： <ul><li><a href="./快速入门/基于SIMD编程/基于SIMD编程.html">SIMD算子快速入门</a></li><li><a href="./快速入门/基于SIMT编程/基于SIMT编程.html">SIMT算子快速入门</a></li></ul></li></ul><hr><h2 id="进阶编程-掌握编程模型-实现定制开发" tabindex="-1">进阶编程：掌握编程模型，实现定制开发 <a class="header-anchor" href="#进阶编程-掌握编程模型-实现定制开发" aria-label="Permalink to &quot;进阶编程：掌握编程模型，实现定制开发&quot;">​</a></h2><p>本阶段聚焦于理解并掌握Ascend C的SIMD与SIMT编程模型，使您具备自主开发矢量及矩阵类算子的能力，从而满足常规场景下的基本性能要求。</p><ul><li><strong>编程模型</strong><ul><li><a href="./../编程指南/编程模型/编程模型.html">编程模型概述</a></li><li><strong>SIMD编程</strong>：<a href="./../编程指南/编程模型/AI-Core-SIMD编程/概述.html">Ascend C SIMD编程模型</a><ul><li><a href="./../编程指南/编程模型/AI-Core-SIMD编程/基于指针的C语言编程/基于语言扩展层C-API编程.html">基于指针的C语言编程</a></li><li><a href="./../编程指南/编程模型/AI-Core-SIMD编程/基于Tensor的C++编程/静态Tensor编程.html">基于Tensor的C++编程</a></li><li><a href="./../编程指南/编程模型/AI-Core-SIMD编程/基于TPipe-TQue框架编程/TPipe-TQue框架编程原理.html">基于TPipe-TQue框架编程</a></li></ul></li><li><strong>SIMT编程</strong>：<a href="./../编程指南/编程模型/AI-Core-SIMT编程/概述.html">Ascend C SIMT编程模型</a></li><li><a href="./../编程指南/语言扩展层/SIMD-BuiltIn关键字.html">语言扩展层概述</a></li></ul></li><li><strong>构建与运行</strong>： <ul><li><a href="./../编程指南/编译与运行/编译与运行.html">编译与运行</a></li></ul></li><li><strong>调试与调优</strong><ul><li><a href="./../编程指南/调试调优/概述.html">调试概述</a></li><li>功能调试：基本调试（print/DumpTensor）、仿真调试、上板调试</li><li>性能调试： <ul><li><a href="./../编程指南/调试调优/性能调优.html">上板性能测试</a></li><li><a href="./../编程指南/调试调优/性能调优.html">仿真性能测试</a></li></ul></li></ul></li><li><strong>算子部署</strong>： <ul><li><a href="./../编程指南/高级编程/高级特性/AI框架算子适配/PyTorch框架.html">PyTorch框架适配</a></li></ul></li><li><strong>实践巩固</strong><ul><li><a href="./../算子实践参考/SIMD算子实现/矢量编程/概述.html">典型SIMD矢量算子开发</a></li><li><a href="./../算子实践参考/SIMD算子实现/矩阵编程（基础API）/分离模式.html">典型SIMD矩阵类算子开发</a></li><li><a href="./../算子实践参考/SIMT算子实现/算子实现.html">典型SIMT算子开发</a></li></ul></li></ul><hr><h2 id="高级编程-挖掘极限性能-驾驭复杂场景" tabindex="-1">高级编程：挖掘极限性能，驾驭复杂场景 <a class="header-anchor" href="#高级编程-挖掘极限性能-驾驭复杂场景" aria-label="Permalink to &quot;高级编程：挖掘极限性能，驾驭复杂场景&quot;">​</a></h2><p>本阶段聚焦于深入理解硬件底层细节，全面掌握高阶编程特性，以支撑实现算子的极致性能目标。</p><ul><li><strong>高级编程</strong><ul><li><a href="./../编程指南/高级编程/硬件实现/基本架构.html">硬件实现</a></li><li><a href="./../编程指南/高级编程/高级AI-Core编程模型/SIMD与SIMT混合编程.html">高级AI Core编程模型</a><ul><li><a href="./../编程指南/高级编程/高级AI-Core编程模型/SIMD与SIMT混合编程.html">SIMD &amp; SIMT混合编程</a></li></ul></li><li><a href="./../编程指南/高级编程/高级特性/AI框架算子适配/概述.html">高级特性</a><ul><li><a href="./../编程指南/高级编程/高级特性/Aclnn算子工程化开发/概述.html">Aclnn算子工程化开发</a></li><li><a href="./../编程指南/高级编程/高级特性/算子入图开发/概述.html">算子入图开发</a></li><li><a href="./../编程指南/高级编程/高级特性/AI框架算子适配/概述.html">AI框架算子适配</a></li></ul></li></ul></li><li><strong>实践巩固</strong><ul><li><a href="./../算子实践参考/SIMD与SIMT混合算子实现/算子实现.html">典型SIMD &amp; SIMT混合算子开发</a></li><li><a href="https://gitcode.com/cann/cann-samples" target="_blank" rel="noreferrer">Ascend C算子高性能实践样例仓</a></li></ul></li><li><strong>跨代迁移</strong><ul><li><a href="./../跨代迁移兼容性指南/概述.html">跨代迁移兼容性指南</a></li></ul></li></ul><hr><h2 id="技术附录" tabindex="-1">技术附录 <a class="header-anchor" href="#技术附录" aria-label="Permalink to &quot;技术附录&quot;">​</a></h2><ul><li><a href="./../技术附录/概念原理和术语/术语表.html">基本概念与术语</a></li><li><a href="./../技术附录/CPP标准支持/概述.html">C++语言标准支持</a></li><li><a href="https://hiascend.com/document/redirect/CannCommunityAscendCApi" target="_blank" rel="noreferrer">Ascend C API参考（含每个API的规格与约束）</a></li></ul>',29)])])}const I=e(r,[["render",n]]);export{d as __pageData,I as default};
